eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   FEATURES: () => (/* binding */ FEATURES),\n/* harmony export */   FLOOR_PLANS: () => (/* binding */ FLOOR_PLANS),\n/* harmony export */   PHOTOS: () => (/* binding */ PHOTOS),\n/* harmony export */   PROPERTY: () => (/* binding */ PROPERTY),\n/* harmony export */   ROOMS: () => (/* binding */ ROOMS)\n/* harmony export */ });\n// =========================================================================\n//  1654 Birchwood Drive — property data\n//\n//  Particulars, agent, and the 17-room schedule below are transcribed from\n//  the active MLS® listing (W12433505) at the time of build. Photography is\n//  forthcoming — PHOTOS / FLOOR_PLANS point at the placeholder graphic at\n//  /gallery/birchwood/placeholder.svg until the professional set is dropped\n//  into /public/gallery/birchwood/ and /public/floorplans/.\n// =========================================================================\nconst PLACEHOLDER_IMG = \"/gallery/birchwood/placeholder.svg\";\nconst PROPERTY = {\n    // ---- core identity ----\n    shortName: \"1654 Birchwood Drive\",\n    address: \"1654 Birchwood Drive, Mississauga, Ontario, L5J 1T6, Canada\",\n    city: \"Mississauga (Lorne Park)\",\n    region: \"Mississauga, Ontario\",\n    postalCode: \"L5J 1T6\",\n    country: \"Canada\",\n    mlsNumber: \"W12433505\",\n    community: \"Lorne Park\",\n    municipality: \"Mississauga\",\n    // GPS — re-pin to surveyed coordinates when available.\n    gps: \"43.5240\\xb0 N, 79.6150\\xb0 W\",\n    latitude: 43.524,\n    longitude: -79.615,\n    // ---- core facts ----\n    bedrooms: \"4 + 1\",\n    bathrooms: \"5 + 1 Half\",\n    livingArea: \"6,600+ sq ft\",\n    lotDimensions: \"88.3 ft \\xd7 118.7 ft\",\n    yearBuilt: \"Recently completed\",\n    propertyTaxes: \"Available upon request\",\n    price: \"$4,598,000\",\n    // numeric values for JSON-LD schema\n    bedroomsNumeric: 5,\n    bathroomsNumeric: 5,\n    livingAreaSqftNumeric: 6600,\n    priceNumeric: 4598000,\n    // ---- positioning ----\n    closingLine: \"A contemporary zen residence in the heart of Lorne Park — modern brick and aluminum cladding, custom millwork, Control4 throughout, and over 6,600 square feet of finished living crafted across four years.\",\n    // ---- listing agent ----\n    agent: {\n        name: \"David Anderson Oey\",\n        title: \"Sales Representative\",\n        brokerage: \"Harvey Kalles Real Estate Ltd., Brokerage\",\n        phone: \"+1 (416) 441-2888\",\n        directPhone: \"+1 (416) 908-9800\",\n        email: \"david@davidoey.com\",\n        website: \"https://davidoey.com\"\n    },\n    // ---- media ----\n    // The hero film is forthcoming. Until the final cut is delivered, this\n    // path 404s harmlessly and the <video> falls back to the poster\n    // (PHOTOS[0] → the placeholder graphic). Drop the compressed MP4 in\n    // /public and update this path. Compress with HandBrake (RF 26 @ 1080p)\n    // to stay under Vercel's 50 MB per-file limit before pushing.\n    droneVideo: \"/birchwood-tour.mp4\",\n    droneVideoIntroEndsAt: 0,\n    droneVideoOutroStartsAt: undefined,\n    // YouTube walkthrough — embedded as its own \"The Walkthrough\" section on\n    // the home page between the Particulars and the Floor Plans chapter.\n    // Source: https://youtu.be/p8HEvjKDwO0\n    filmYouTubeId: \"p8HEvjKDwO0\"\n};\n// -------------------------------------------------------------------------\n//  Photography — placeholders until the professional set is delivered.\n//  PHOTOS[0] drives the hero poster; later entries feed the section-break\n//  callouts. Replace src values with /gallery/birchwood/<file>.jpg as photos\n//  come in.\n// -------------------------------------------------------------------------\nconst PHOTOS = [\n    {\n        src: \"/gallery/birchwood/001-1900x-photo.jpg\",\n        alt: \"1654 Birchwood Drive — front elevation at twilight.\",\n        kind: \"exterior\"\n    },\n    {\n        src: \"/gallery/birchwood/002-1900x-photo.jpg\",\n        alt: \"1654 Birchwood Drive — exterior approach.\",\n        kind: \"exterior\"\n    },\n    {\n        src: \"/gallery/birchwood/050-1900x-photo.jpg\",\n        alt: \"1654 Birchwood Drive — interior.\",\n        kind: \"interior\"\n    },\n    {\n        src: \"/gallery/birchwood/118-1900x-photo.jpg\",\n        alt: \"1654 Birchwood Drive — aerial view.\",\n        kind: \"drone\"\n    }\n];\n// -------------------------------------------------------------------------\n//  Floor plans — drop architectural plates into /public/floorplans/ and\n//  list them here. Empty for now; the page shows a \"forthcoming\" note.\n// -------------------------------------------------------------------------\nconst FLOOR_PLANS = [];\nconst ROOMS = [\n    {\n        title: \"The Foyer\",\n        body: \"A dramatic twenty-foot arrival framed by an illuminated glass pivot door — the first room sets the grammar for the residence: floating staircase, architectural feature panel walls, light-filled volumes, and the custom millwork that runs the length of the home.\",\n        imageSrc: \"/gallery/birchwood/010-1900x-photo.jpg\",\n        meta: \"Main \\xb7 20-ft Ceiling \\xb7 Pivot Door\"\n    },\n    {\n        title: \"The Living Room\",\n        body: \"A generous principal room on the main level — refined cabinetry, heated floors, and the considered restraint that defines the rest of the house. Sized for entertaining and a quiet evening in equal measure.\",\n        imageSrc: \"/gallery/birchwood/017-1900x-photo.jpg\",\n        meta: \"Main \\xb7 5.2 m \\xd7 5.334 m \\xb7 17′1″ \\xd7 17′6″\"\n    },\n    {\n        title: \"The Dining Room\",\n        body: \"Matched in scale to the living room and detailed with the same architectural language — heated floors, custom millwork, and skylights overhead. Set for a long table of ten with room to spare.\",\n        imageSrc: \"/gallery/birchwood/022-1900x-photo.jpg\",\n        meta: \"Main \\xb7 5.2 m \\xd7 5.334 m \\xb7 17′1″ \\xd7 17′6″\"\n    },\n    {\n        title: \"The Family Room\",\n        body: \"A modern, comfort-first room anchored by a striking two-sided linear fireplace that opens between the family room and the principal floor. Twenty-one feet across, open to the kitchen, and built to live in.\",\n        imageSrc: \"/gallery/birchwood/029-1900x-photo.jpg\",\n        meta: \"Main \\xb7 6.5 m \\xd7 5.27 m \\xb7 21′4″ \\xd7 17′3″\"\n    },\n    {\n        title: \"The Chef's Kitchen\",\n        body: \"Twenty-two feet across, fitted with the full Miele appliance suite and a PITT gas counter range — the cooktop set directly into the stone. A separate catering kitchen handles the heavier work; the main kitchen stays the room the family lives in.\",\n        imageSrc: \"/gallery/birchwood/031-1900x-photo.jpg\",\n        meta: \"Main \\xb7 6.7 m \\xd7 5.27 m \\xb7 22′0″ \\xd7 17′3″\"\n    },\n    {\n        title: \"The Executive Office\",\n        body: \"A bespoke main-floor study with custom millwork on every wall and a window framed onto the treetops. The proper home office a post-2020 buyer expects — quiet, private, and built for the long workday.\",\n        imageSrc: \"/gallery/birchwood/040-1900x-photo.jpg\",\n        meta: \"Main \\xb7 3.87 m \\xd7 3.35 m \\xb7 12′8″ \\xd7 11′0″\"\n    },\n    {\n        title: \"The Mud Room\",\n        body: \"The unromantic working room that makes the rest of the house easier to live in — custom millwork, refined cabinetry, and direct flow to the garage and the principal floor.\",\n        imageSrc: \"/gallery/birchwood/044-1900x-photo.jpg\",\n        meta: \"Main \\xb7 3.1 m \\xd7 2.4 m \\xb7 10′2″ \\xd7 7′10″\"\n    },\n    {\n        title: \"The Primary Suite\",\n        body: \"A private retreat at the quiet end of the second floor — a spa-inspired ensuite, custom walnut-and-glass walk-in closets, and a cozy lounge anchored by a three-sided fireplace that throws ambient light across the room.\",\n        imageSrc: \"/gallery/birchwood/050-1900x-photo.jpg\",\n        meta: \"Second \\xb7 5.5 m \\xd7 4.9 m \\xb7 18′1″ \\xd7 16′1″\"\n    },\n    {\n        title: \"Bedroom Two\",\n        body: \"A generous secondary bedroom with its own en-suite bath and built-in cabinetry — the kind of room that doesn't read as secondary at all.\",\n        imageSrc: \"/gallery/birchwood/058-1900x-photo.jpg\",\n        meta: \"Second \\xb7 4.26 m \\xd7 4.4 m \\xb7 14′0″ \\xd7 14′5″\"\n    },\n    {\n        title: \"Bedroom Three\",\n        body: \"A second en-suite bedroom on the upper level, fitted with built-in cabinetry and the same considered detailing carried through the rest of the home.\",\n        imageSrc: \"/gallery/birchwood/062-1900x-photo.jpg\",\n        meta: \"Second \\xb7 4.26 m \\xd7 3.9 m \\xb7 14′0″ \\xd7 12′10″\"\n    },\n    {\n        title: \"Bedroom Four \\xb7 Flex Suite\",\n        body: \"A flexible fourth bedroom suite designed to read as a nursery, a study, a guest room, or a creative space — built-in cabinetry, en-suite access, and the room to be whatever the household needs it to be.\",\n        imageSrc: \"/gallery/birchwood/066-1900x-photo.jpg\",\n        meta: \"Second \\xb7 3.3 m \\xd7 2.5 m \\xb7 10′10″ \\xd7 8′2″\"\n    },\n    {\n        title: \"The Laundry Room\",\n        body: \"Full custom millwork, a generous countertop run, and a quiet workhorse layout on the upper level — the kind of laundry room that makes the daily routine feel considered.\",\n        imageSrc: \"/gallery/birchwood/070-1900x-photo.jpg\",\n        meta: \"Second \\xb7 3.6 m \\xd7 1.5 m \\xb7 11′10″ \\xd7 4′11″\"\n    },\n    {\n        title: \"The Theatre\",\n        body: \"A fifteen-seat soundproof home theatre on the lower level — the showpiece of the entertainment wing. Built for film nights, sports finals, and the household weekends that don't have to leave home.\",\n        imageSrc: \"/gallery/birchwood/082-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 5.1 m \\xd7 5.73 m \\xb7 16′9″ \\xd7 18′10″\"\n    },\n    {\n        title: \"The Recreation Room\",\n        body: \"An open-concept games room anchored by a sleek wet bar and looking out onto the landscaped grounds — the casual room of the lower level.\",\n        imageSrc: \"/gallery/birchwood/075-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 4.75 m \\xd7 3 m \\xb7 15′7″ \\xd7 9′10″\"\n    },\n    {\n        title: \"The Catering Kitchen\",\n        body: \"A second, lower-level kitchen that doubles as the bar's pantry and the in-law suite's working space — sized to host or to support an extended stay below grade.\",\n        imageSrc: \"/gallery/birchwood/086-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 4.75 m \\xd7 4 m \\xb7 15′7″ \\xd7 13′1″\"\n    },\n    {\n        title: \"The Exercise Room\",\n        body: \"A dedicated, open-concept gym — twenty feet across, designed to hold a full home-fitness set-up with room to move. The wellness anchor of the lower level.\",\n        imageSrc: \"/gallery/birchwood/092-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 6.1 m \\xd7 2.5 m \\xb7 20′0″ \\xd7 8′2″\"\n    },\n    {\n        title: \"Bedroom Five \\xb7 Nanny / Guest Suite\",\n        body: \"A nanny or guest suite with its own spa-like ensuite and a direct walkout to the landscaped grounds — privacy for an extended stay, accessibility for daily help.\",\n        imageSrc: \"/gallery/birchwood/097-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 3.1 m \\xd7 3.5 m \\xb7 10′2″ \\xd7 11′6″\"\n    },\n    {\n        title: \"The Wine Cantina\",\n        body: \"A glass-walled, temperature-controlled wine cantina set into the lower level — both functional storage and a visual centrepiece of the entertaining floor.\",\n        imageSrc: \"/gallery/birchwood/088-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 Temperature-Controlled\"\n    },\n    {\n        title: \"Cold Cellar\",\n        body: \"A cool, dry, dedicated storage room for the household's seasonal pantry — the practical complement to the wine cantina next door.\",\n        imageSrc: \"/gallery/birchwood/071-1900x-photo.jpg\",\n        meta: \"Lower \\xb7 3.35 m \\xd7 1.22 m \\xb7 11′0″ \\xd7 4′0″\"\n    }\n];\n// -------------------------------------------------------------------------\n//  Highlight features pulled from the listing description — surfaced in\n//  the Particulars block as a short, scannable list of what makes this\n//  residence specific.\n// -------------------------------------------------------------------------\nconst FEATURES = {\n    exterior: [\n        \"Modern brick and aluminum cladding\",\n        \"Beautifully landscaped grounds with irrigation\",\n        \"Architectural exterior lighting\",\n        \"Wooded, flat site\"\n    ],\n    interior: [\n        \"20-foot foyer with illuminated glass pivot door\",\n        \"Floating staircase\",\n        \"Architectural feature-panel walls\",\n        \"Custom millwork throughout\",\n        \"Heated floors and skylights\",\n        \"Two-sided linear fireplace \\xb7 main floor\",\n        \"Three-sided fireplace \\xb7 primary lounge\",\n        \"Miele appliance suite\",\n        \"PITT gas counter range\",\n        \"Separate catering kitchen\",\n        \"Custom walnut-and-glass walk-in closets\",\n        \"Carpet free\"\n    ],\n    security: [\n        \"Control4 smart-home automation\"\n    ]\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/property.ts\n");

